<section class="panel"><div class="panel-head"><div><span class="eyebrow">HAREKET GEÇMİŞİ</span><h3>Son depo transferleri</h3></div><span class="result-count"><?= count($transfers) ?> kayıt</span></div><div class="table-wrap"><table class="data-table"><thead><tr><th>Transfer no</th><th>Kaynak</th><th>Hedef</th><th>Ürün</th><th>İşlemi yapan</th><th>Tarih</th></tr></thead><tbody><?php foreach($transfers as $t): ?><tr><td><strong><?= kd_e($t['transfer_number']) ?></strong><?php if($t['note']): ?><small class="table-sub"><?= kd_e($t['note']) ?></small><?php endif; ?></td><td><?= kd_e($t['from_name']) ?></td><td><?= kd_e($t['to_name']) ?></td><td><?= (int)$t['item_count'] ?></td><td><?= kd_e($t['user_name']?:'Sistem') ?></td><td><?= kd_e(date('d.m.Y H:i',strtotime((string)$t['created_at']))) ?></td></tr><?php endforeach; ?><?php if(!$transfers): ?><tr><td colspan="6" class="empty-state">Henüz transfer kaydı yok.</td></tr><?php endif; ?></tbody></table></div></section>
